ap=argparse.ArgumentParser();ap.add_argument('--input',required=True);ap.add_argument('--stage',required=True);args=ap.parse_args();h=ROOT/'.local-models/geometry-workbench/heart';src=h/args.input;meta=json.loads((src/'ownership.json').read_text());out=h/args.stage;out.mkdir(exist_ok=False);z=np.load(src/'arrangement.npz');p=z['positions'];q=p.astype('<f4').astype(float);surfaces={r['id']:z[r['faces']]for r in meta['surfaces']};words={r['id']:z[r['normals']]for r in meta['surfaces']};uvs={r['id']:z[r['uvs']]for r in meta['surfaces']};rows=[];start=time.monotonic()
